import{z as B,x as L,o as l,c as n,q as r,j as o,D as e,d as s,s as i,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"LLDP","description":"","frontmatter":{"title":"LLDP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lldp.md","filePath":"cs/lldp.md","lastUpdated":1791063341000}'),p={name:"cs/lldp.md"};function d(P,a,D,T,C,h){const t=L("Mermaid");return l(),n("div",null,[a[2]||(a[2]=r('<h1 id="lldp" tabindex="-1">LLDP <a class="header-anchor" href="#lldp" aria-label="Permalink to &quot;LLDP&quot;">​</a></h1><div class="epigraph"><p>邻机用 TLV 说出自己的机箱、口名与能力；链路层发现不转发业务，只填一张谁连着谁的图。</p><footer>—— 据 IEEE 802.1AB LLDP；TIA-1057 LLDP-MED 整理</footer></div><p><a href="/cs/lacp">上一课</a>把多口收成逻辑边，运维仍可能插错线。缺口是<strong>邻居发现</strong>：LLDP 在链路上组播自己的 chassis ID、port ID、TTL，对端写入 MIB。本课不把 RSTP 握手写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ARP 与 ICMP 发现的是三层可达。插错 VLAN、插错 LACP 成员，需要二层「你是谁」。LLDP：目的 MAC 是 01-80-C2-00-00-0E，桥不转发（与某些厂商 CDP 行为对照）。TLV 可带管理地址、IEEE 802.3 能力、MED 给话机供电与 VLAN。TTL 到期则表项消失——邻居离开不必显式再见。</p><p>不要把 LLDP 当认证：未加密，可伪造，只是运维平面。</p><p><span class="marginnote">术语翻译：TLV 就是「类型-长度-值」三段式小卡片——先报这是什么信息（类型），再说它多长（长度），最后是内容本身；一条 LLDP 帧里串着好几张这样的卡片（机箱、口名、能力……）。</span></p><p><span class="marginnote">802.1AB 定义 PDU 与 MIB。CDP 是 Cisco 对照，本课不展开。本课不把 802.1X 证书当 LLDP 的一部分。</span></p><h3 id="发现不是认证" tabindex="-1">发现不是认证 <a class="header-anchor" href="#发现不是认证" aria-label="Permalink to &quot;发现不是认证&quot;">​</a></h3><p>明文 TLV 服务布线对账，可伪造。桥不转发该组播。邻居 TTL 老化，不必显式再见。不改转发拓扑。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每口周期发 LLDP 帧；收则刷新。画：口 → 邻居表（系统名、口描述）。与自协商对照：协商选速率，LLDP 选「人读得懂的名字」。LACP 成员口上 LLDP 仍按物理口报告，便于查捆错。</p><p><span class="marginnote">数字实例：默认发送间隔约 30 秒，TTL 常取其约 4 倍（120 秒）。对端 120 秒内没再听到你，就自动删掉你的表项——拔线或断电后邻居图自己变干净，不需要谁去显式道别。</span></p>',13)),(l(),o(A,null,{default:e(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TX%5B%22%E5%91%A8%E6%9C%9F%E7%BB%84%E6%92%AD%20TLV%22%5D%20--%3E%20NB%5B%22%E5%AF%B9%E7%AB%AF%E9%82%BB%E5%B1%85%E8%A1%A8%22%5D%0A%20%20NB%20--%3E%20OPS%5B%22%E5%AF%B9%E8%B4%A6%E5%B8%83%E7%BA%BF%E4%B8%8E%20LAG%22%5D%0A%20%20TX%20--%3E%20EXP%5B%22TTL%20%E5%88%B0%E6%9C%9F%E5%88%A0%E9%99%A4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"生成树 BPDU 也是链路组播，但目的是算树；LLDP 不改转发拓扑。两者可同口并存。交换机架构后课的控制面 CPU 处理这些慢协议，数据面不查 LLDP。",-1)),a[5]||(a[5]=E("p",null,"MED：话机告诉交换机 PoE 与语音 VLAN，仍是 TLV，不是呼叫信令。",-1)),(l(),o(A,null,{default:e(()=>[i(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20F%5B%22LLDP%20%E5%B8%A7%EF%BC%9A%E7%9B%AE%E7%9A%84%2001-80-C2-00-00-0E%22%5D%20--%3E%20T1%5B%22TLV%EF%BC%9AChassis%20ID%EF%BC%88%E6%9C%AC%E6%9C%BA%E6%98%AF%E8%B0%81%EF%BC%89%22%5D%0A%20%20T1%20--%3E%20T2%5B%22TLV%EF%BC%9APort%20ID%EF%BC%88%E4%BB%8E%E5%93%AA%E4%B8%AA%E5%8F%A3%E5%8F%91%E5%87%BA%EF%BC%89%22%5D%0A%20%20T2%20--%3E%20T3%5B%22TLV%EF%BC%9ATTL%EF%BC%88%E8%A1%A8%E9%A1%B9%E6%9C%89%E6%95%88%E6%9C%9F%E7%A7%92%E6%95%B0%EF%BC%89%22%5D%0A%20%20T3%20--%3E%20IN%5B%22%E5%AF%B9%E7%AB%AF%E6%94%B6%E4%B8%8B%E5%86%99%E5%85%A5%E9%82%BB%E5%B1%85%E8%A1%A8%EF%BC%8C%E5%88%B0%E6%AD%A4%E4%B8%BA%E6%AD%A2%EF%BC%8C%E4%B8%8D%E5%86%8D%E8%BD%AC%E5%8F%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 sFlow 采样。RSTP/MSTP 是下一课。后课默认：LLDP 提供一跳身份，不提供可达性证明。</p><p>关闭 LLDP 的安全理由是减少侦察；那是权衡，不是协议缺陷清单。</p><p><span class="marginnote">常见误区：以为「听得到邻居」就等于「可达邻居的邻居」。LLDP 帧在第一跳就被收下、不转发，它只证明这条线两端连着谁，不证明多跳可达性——跨多台设备的路径要靠路由和生成树另说。</span></p><p>下一课<a href="/cs/rstp-mstp">RSTP / MSTP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LLDP 用不可转发组播交换一跳身份。</li><li>TTL 老化邻居；不替代 STP 或 LACP。</li><li>明文、可伪造，服务运维。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.1AB；LLDP-MED。</li></ul>',7))])}const F=B(p,[["render",d]]);export{c as __pageData,F as default};
